import type { ComponentType } from "react";
import type { MDXComponents } from "mdx/types";
import type { Accent } from "@/content/nav";

/** Metadata that travels with every page chunk (generated by scripts/vite-docs-plugin.mjs). */
export type PageMeta = {
  path: string;
  sectionId: string | null;
  navTitle: string;
  title: string;
  description: string;
  plan?: "honey" | "swarm" | "royal";
  accent: Accent;
  headings: { text: string; id: string }[];
  hidden: boolean;
};

export type PageModule = {
  default: ComponentType<{ components?: MDXComponents }>;
  meta: PageMeta;
};

export type NavItem = { slug: string; title: string; path: string; group?: string };

export type NavSectionData = {
  id: string;
  label: string;
  icon: string;
  accent: Accent;
  summary: string;
  pages: NavItem[];
};
